import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
const clone = '/home/jack/.t3/bench-runs-lanes/codex-thermo-sol61/2026-10-10-last-push-codex-thermo-sol61/att-017/clone';
async function load(fixture, name) {
  const root = `${clone}/packages/integrations/vercel/test/fixtures/${fixture}/.vercel/output/functions/${name}.func/`;
  const config = JSON.parse(await readFile(`${root}.vc-config.json`, 'utf8'));
  return (await import(pathToFileURL(`${root}${config.handler}`))).default;
}
async function call(label, handler, path, headers, expectedStatus, expectedText) {
  const response = await handler.fetch(new Request(`https://example.com${path}`, { headers }));
  const text = await response.text();
  assert.equal(response.status, expectedStatus);
  if (expectedText !== undefined) assert.equal(text, expectedText);
  console.log(JSON.stringify({ label, status: response.status, body: text.length < 120 ? text : text.includes('<h1>One</h1>') ? 'contains <h1>One</h1>' : 'HTML' }));
}
const render = await load('serverless-with-dynamic-routes', '_render');
