await call('render control: ISR marker zero', render, '/api/public?x_astro_path=/api/private', { 'x-vercel-isr': '0' }, 200, '{"id":"public"}');
await call('render: ISR marker one selects private', render, '/api/public?x_astro_path=/api/private', { 'x-vercel-isr': '1' }, 200, '{"id":"private"}');
await call('render: invalid secret does not prevent override', render, '/api/public?x_astro_path=/api/private', { 'x-vercel-isr': '1', 'x-astro-middleware-secret': 'invalid' }, 200, '{"id":"private"}');
await call('render: locals remain protected', render, '/api/public?x_astro_path=/api/private', { 'x-vercel-isr': '1', 'x-astro-locals': '{}' }, 403, 'Forbidden');
const isr = await load('isr', '_isr');
await call('ISR control: missing marker', isr, '/_isr?x_astro_path=/one', {}, 404);
await call('ISR intended recovery', isr, '/_isr?x_astro_path=/one', { 'x-vercel-isr': '1' }, 200);
const excludedRender = await load('isr', '_render');
await call('excluded API control', excludedRender, '/api/public?x_astro_path=/api/private', {}, 200, 'OK public');
await call('excluded API also accepts ISR marker', excludedRender, '/api/public?x_astro_path=/api/private', { 'x-vercel-isr': '1' }, 200, 'OK private');
EOF
